var localName = API.cache('localName');
var species = get('specieSelection') || [];
var helper = API.cache('helper');
if(!helper) {
    helper = new ChemEquilibrium.Helper();
    API.cache('helper', helper);
}

localStorage.setItem(localName, JSON.stringify(species));
helper.resetSpecies();
for(var i=0; i<species.length; i++) {
    var specie = species[i];
    console.log(specie)
    helper.addSpecie(String(specie.label), Number(specie.qty));
}

(API.getData('equations') || []).forEach(e => {
    if(DataObject.resurrect(e.disabled)) {
        console.log('disable equation', e.chemEq.formed);
        helper.disableEquation(String(e.chemEq.formed));
    } else {
        helper.enableEquation(String(e.chemEq.formed));
    }
});

var chemEq = helper.getEquations({filtered: true, includeDisabled: true});
console.log(chemEq)
var normalizedEq = helper.getEquations({filtered: true, normalized: true, includeDisabled: true});
var equations = chemEq.map((eq, idx) => {
    return {
        chemEq: eq,
        normalizedEq: normalizedEq[idx],
        disabled: eq.disabled ? true : false
    }
});
API.createData('equations', equations);

API.doAction('trigger')

var helper = new ChemEquilibrium.Helper();
//{type: 'precipitation'}
var species = helper.getSpecies()
    .map(function(label) {
        return {
            label: label,
            qty: 1
        }
    });

API.createData('allSpecies', species);

var species = API.getData('specieSelection') || [];
var config = {
  "varying": "H+",
  "isFixed": true,
  "from": 0,
  "to": 14,
  "log": true,
  "tolerance": 1e-15,
  "solidTolerance": 1e-10,
  "maxIterations": 200,
  "chunks": 500
};

var helper = API.cache('helper');
if(!helper) {
    UI.showNotification('Not ready to compute equilibriums');
    return;
}

var Serie = ChemEquilibrium.Serie;
var serie = new Serie(helper);
var sol = serie.getSolutions(config);

var chart = Chart.getChart(sol.x, sol.solutions, {
    xLabel: config.isFixed ? ('Quantity ' + (config.log ? '-log10 of ' : 'of ') + config.varying + 'at equilibrium ' + config.log ? '' : '[mol]') : ('Total quantity of ' + config.varying),
    yLabel: 'Amount of other species at equilibrium [mol]'
});


API.createData('errorCount', sol.errorCount);
API.createData('chartSpecies', sol.species.map( specie => specie.replace(/(-+)/,'($1)')));
API.createData('chart', chart);
API.createData('model', helper.getModel());

// Documentation: https://github.com/NPellet/visualizer/blob/db85d9cc12c6204e4a3afb69bba6d695f6f8bad5/src/modules/types/edition/slick_grid/view.js#L918-L940
var localName = API.cache('localName');

if(this.event === 'rowsSelected') {
    try {
        var rows = JSON.parse(localStorage.getItem(localName));
    } catch(e) {
        rows = []
    }
    console.log(rows);
    API.createData('specieSelection', this.rows.map(row => {
        var obj = {};
        obj.label = String(row.item.label);
        var r = rows.find(r => r.label === obj.label); 
        if(r) {
            obj.qty = r.qty;
        } else {
            obj.qty = row.item.qty;
        }
        return obj;
    }));
}

